   std::vector<double> B;
   B.insert(B.begin(), A.data(), A.data()+A.size());
   return &B[i];
}

int main(int argc, char** argv)
{
   using namespace std;

   BenchTimer t1,t2,t3;
   int tries = 10;
   int rep = 1000;
   int n = 100000;
   VectorXd A(n);
   A.setRandom();
   BENCH(t1,tries,rep,cp1(A));
   BENCH(t2,tries,rep,cp2(A));
   BENCH(t3,tries,rep,cp3(A));
   cout << t1.best() << " ; " << t2.best() << " ; " << t3.best() << endl;
}

